key: z.string(),
value: z.unknown(),
}),
});

name: "memory_get",
description: "Look up a memory stored in the user's browser.",
schema: z.object({
key: z.string(),
}),
});

name: "geolocation_get",
description: "Get the user's current location from the browser.",
schema: z.object({
save: z.boolean().optional(),
}),
});
```

