```python
from langgraph.types import Command # [!code highlight]

resume = {}
for interrupt_ in interrupts:
action_request = interrupt_.value["action_requests"][0]
if action_request["name"] == "send_email":
# Edit email
edited_action = {
"name": action_request["name"],
"args": {**action_request["args"], "subject": "Mockups reminder"},
}
resume[interrupt_.id] = {
"decisions": [{"type": "edit", "edited_action": edited_action}]
}
else:
resume[interrupt_.id] = {"decisions": [{"type": "approve"}]}

interrupts = []
stream = supervisor_agent.stream_events(
Command(resume=resume), # [!code highlight]
config,
version="v3",
)
for kind, item in stream.interleave("messages", "tool_calls"):
if kind == "messages":
for token in item.text:
print(token, end="", flush=True)
elif kind == "tool_calls":
print(f"\nTool call: {item.tool_name}({item.input})")
if stream.interrupted:
for interrupt_ in stream.interrupts:
interrupts.append(interrupt_)
print(f"\nINTERRUPTED: {interrupt_.id}")
